1const checkPrime = (number) => {
2    if (number <= 1) {
3        return false;
4    }
5    
6    if (number > 1) {
7        for (let i = 2; i < number; i++) {
8            if (number % i === 0) {
9                return false;
10            }
11        }
12        return true;
13    }
14}
